responseFormat.typescriptTypesReference:
type Citation = {
commentId: number;
};

type Clause = {
text: string;
citations: Citation[];
};

type Sentence = {
clauses: Clause[];
};

type Paragraph = {
id: string; // e.g. "group_overview"
title: string;
sentences: Sentence[];
};

type Subtask = {
id: string;
title: string;
paragraphs: Paragraph[];
};

polisAnalysisPrompt.example:
{
"id": "group_differences",
"title": "Tribe Differences",
"paragraphs": [
{
"id": "group_overview",
"title": "Overview of Tribe Differences",
"sentences": [
{
"clauses": [
{
"text": "The conversation contains 3 distinct tribes with different perspectives on key issues.",
"citations": [12, 15, 23]
}
]
}
]
}
]
}
